    @classmethod
    def _complete_excerpt(cls, text: str | None, limit: int = 120) -> str:
        """Keep a complete short sentence; never manufacture an ellipsis."""
        value = cls._clean_text(text)
        if len(value) <= limit:
            return value
        matches = list(re.finditer(r"[。！？.!?](?:[”’\"）)\]]*)", value[: limit + 1]))
